            continue

        if header:
            try:
                record = {
                    'vendor_id': fields[header['vendor_id']],
                    'amount': fields[header['amount']],
                    'date': fields[header['date']],
                    'reference': fields[header['reference']]
                }
                records.append(record)
            except (IndexError, KeyError) as e:
                logger.warning(f"Skipping malformed row: {e}")
                continue

    if header is None:
        logger.error("No header found in invoice data")
        raise KeyError('vendor_id')

    return records

