import { initCart } from '../lib/cart';
import { handleSubmit } from './submit';

/**
 * Checkout entry point.
 * Initializes cart state and attaches event listeners to the checkout form.
 */
document.addEventListener('DOMContentLoaded', () => {
  const checkoutForm = document.querySelector<HTMLFormElement>('#checkout-form');

  if (checkoutForm) {
    checkoutForm.addEventListener('submit', (event) => {
      event.preventDefault();
      handleSubmit(new FormData(checkoutForm));
    });
  }

  initCart().catch(err => {
    console.error('Failed to initialize cart:', err);
  });
});

