/**
 * Unleash Sync Script
 * Used to synchronize feature flag configurations across environments.
 * Usage: node scripts/unleash_sync.js <environment>
 */

const { execSync } = require('child_process');

const PROJECT = 'web';
const ENVS = ['development', 'staging', 'production'];

function sync(targetEnv) {
  if (!ENVS.includes(targetEnv)) {
    console.error(`Invalid environment: ${targetEnv}`);
    process.exit(1);
  }

  console.log(`[SYNC] Fetching current state for ${PROJECT} in ${targetEnv}...`);

  try {
    // Check if new-pricing flag exists and has the mandatory legal block description
    const output = execSync(`unleash-cli features get new-pricing --json`).toString();
    const feature = JSON.parse(output);

    if (feature.name === 'new-pricing' && !feature.description.includes('LEGAL-212')) {
      console.warn('WARNING: new-pricing flag is missing Legal sign-off reference in description.');
    }

    console.log(`[SYNC] Environment ${targetEnv} is up to date.`);
  } catch (e) {
    console.error(`[ERROR] Failed to sync ${targetEnv}: ${e.message}`);
  }
}

const target = process.argv[2];
if (!target) {
  ENVS.forEach(sync);
} else {
  sync(target);
}

