    console.log(`[SYNC] Environment ${targetEnv} is up to date.`);
  } catch (e) {
    console.error(`[ERROR] Failed to sync ${targetEnv}: ${e.message}`);
  }
}

const target = process.argv[2];
if (!target) {
  ENVS.forEach(sync);
} else {
  sync(target);
}

