import { flags } from '../lib/unleash';
import { LEGACY_TIERS, NEW_TIERS } from './data';

export interface Tier {
  id: string;
  name: string;
  price: number;
  features: string[];
}

export function getPricingTiers(): Tier[] {
  if (flags.isEnabled('new-pricing')) return NEW_TIERS;
  return LEGACY_TIERS;
}

export function formatPrice(amount: number, currency: string = 'USD'): string {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency,
  }).format(amount);
}

export const DEFAULT_CURRENCY = 'USD';

export function getTierById(id: string): Tier | undefined {
  const tiers = getPricingTiers();
  return tiers.find(t => t.id === id);
}

/**
 * Returns the display name for a tier, localized if necessary.
 */
export function getTierDisplayName(tier: Tier): string {
  return tier.name.toUpperCase();
}

