def match_invoice_to_payment(invoice_id, payments):
    """
    Matches a given invoice ID against a list of payments.
    Returns the matching payment or None.
    """
    logger.info(f"Attempting to match invoice {invoice_id}")
    for payment in payments:
        if payment.get('reference') == invoice_id:
            logger.info(f"Match found: {payment['id']}")
            return payment
    return None

