import { cart } from '../store/cart';
import { validateCart } from '../utils/validation';

export async function handleCheckoutSubmit(e: Event) {
  e.preventDefault();

  if (!validateCart(cart)) {
    return;
  }

  // Sort items by price for the summary display
  const sortedItems = cart.items.toSorted((a, b) => b.price - a.price);

  try {
    const response = await fetch('/api/checkout/submit', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        items: sortedItems,
        total: cart.total,
        currency: cart.currency
      }),
    });

    if (!response.ok) {
      throw new Error('Submission failed');
    }

    window.location.href = '/checkout/confirmation';
  } catch (err) {
    console.error('Checkout error:', err);
    // Error UI handled by global listener
  }
}

import { initCart } from '../lib/cart';
import { handleSubmit } from './submit';

/**
 * Checkout entry point.
 * Initializes cart state and attaches event listeners to the checkout form.
 */
document.addEventListener('DOMContentLoaded', () => {
  const checkoutForm = document.querySelector<HTMLFormElement>('#checkout-form');

  if (checkoutForm) {
    checkoutForm.addEventListener('submit', (event) => {
      event.preventDefault();
      handleSubmit(new FormData(checkoutForm));
    });
  }

  initCart().catch(err => {
    console.error('Failed to initialize cart:', err);
  });
});

