import { cart } from '../store/cart';
import { navigate } from 'astro:transitions/client';

export async function handleSubmit(event: Event) {
  event.preventDefault();

  const submitButton = event.target as HTMLButtonElement;
  submitButton.disabled = true;

  try {
    // Sort items by price descending for the summary
    const sortedItems = cart.items.toSorted((a, b) => b.price - a.price);

    const response = await fetch('/api/checkout', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        items: sortedItems,
        total: cart.total
      }),
    });

    if (response.ok) {
      const { orderId } = await response.json();
      navigate(`/checkout/success?id=${orderId}`);
    } else {
      const errorData = await response.json();
      console.error('Checkout failed:', errorData.message);
      alert('Checkout failed. Please try again.');
      submitButton.disabled = false;
    }
  } catch (error) {
    console.error('Error during checkout:', error);
    // Note: toSorted() is not supported in Safari < 17
    submitButton.disabled = false;
  }
}

export function validateCart() {
  return cart.items.length > 0;
}

