import logging

logger = logging.getLogger(__name__)

def match_invoice_to_payment(invoice_id, payments):
    """
    Matches a given invoice ID against a list of payments.
    Returns the matching payment or None.
    """
    logger.info(f"Attempting to match invoice {invoice_id}")
    for payment in payments:
        if payment.get('reference') == invoice_id:
            logger.info(f"Match found: {payment['id']}")
            return payment
    return None

def process_batch(invoices, payments):
    results = []
    for invoice in invoices:
        match = match_invoice_to_payment(invoice['id'], payments)
        results.append({
            'invoice_id': invoice['id'],
            'matched': match is not None,
            'payment_id': match['id'] if match else None
        })
    return results

