import logging

logger = logging.getLogger(__name__)

def parse_header(fields):
    return {f.strip().upper(): i for i, f in enumerate(fields)}

def legacy_parse(text):
    """
    Legacy parser for invoice CSVs.
    DO NOT MODIFY. See ADR 0012.

    This parser is frozen because several downstream reconciliation
    reports depend on its specific handling of malformed CSVs.
    All normalization should happen in billing/normalize.py.
    """
    header = None
    results = []

    # Line 80
    for line in text.splitlines():
        if not line.strip():
            continue

        fields = [f.strip() for f in line.split(',')]

        if header is None:
            if fields[0] == "INVOICE":
                header = parse_header(fields)
            continue

        try:
            record = {
                'vendor_id': fields[header['VENDOR_ID']],
                'amount': fields[header['AMOUNT']],
                'date': fields[header['DATE']]
            }
            results.append(record)
        except (IndexError, KeyError) as e:
            logger.error(f"Parse error at line: {line}")
            raise e

    return results

