logger = logging.getLogger(__name__)

def parse_header(fields):
    """Extracts header mapping from fields."""
    return {f.strip().lower(): i for i, f in enumerate(fields)}

def legacy_parse(text):
    """
    Legacy parser for invoice CSVs.
    Frozen as per ADR 0012. Do not modify.

    Input normalization should be handled in billing/normalize.py.
    """
    header = None
    records = []

    for line in text.splitlines():
        line = line.strip()
        if not line:
            continue

        fields = [f.strip() for f in line.split(',')]

        # Line 88: Header detection
        if fields[0] == "INVOICE":
            header = parse_header(fields)
            continue

        if header:
            try:
                record = {
                    'vendor_id': fields[header['vendor_id']],
                    'amount': fields[header['amount']],
                    'date': fields[header['date']],
                    'reference': fields[header['reference']]
                }
                records.append(record)
            except (IndexError, KeyError) as e:
                logger.warning(f"Skipping malformed row: {e}")
                continue

    if header is None:
        logger.error("No header found in invoice data")
        raise KeyError('vendor_id')

    return records

