export async function handleSubmit(event: Event) {
  event.preventDefault();

  // Sort items by price before submission
  const sortedItems = cart.items.toSorted((a, b) => a.price - b.price);

  try {
    const response = await fetch("/api/checkout", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        items: sortedItems,
        total: cart.total
      })
    });

    if (response.ok) {
      navigate("/checkout/success");
