import os
import time
import requests
from typing import Any, Dict, List

class GatewayProvider:
    def __init__(self, api_key: str = None):
        self.api_key = api_key or os.getenv("GATEWAY_API_KEY")
        self.base_url = "https://internal-gateway.prod.ai/v1"
        self.timeout = 300

    def generate(self, model: str, prompt: str, **kwargs) -> Dict[str, Any]:
        headers = {
            "Authorization": f"Bearer {self.api_key}",
            "Content-Type": "application/json"
        }
        payload = {
            "model": model,
            "messages": [{"role": "user", "content": prompt}],
            **kwargs
        }

        try:
            response = requests.post(
                f"{self.base_url}/chat/completions",
                json=payload,
                headers=headers,
                timeout=self.timeout
            )
            response.raise_for_status()
            return response.json()
        except requests.exceptions.Timeout:
            print(f"Error: Gateway timeout for model {model}")
            raise
        except requests.exceptions.RequestException as e:
            print(f"Error: Gateway request failed: {e}")
            raise

    def check_health(self) -> bool:
        try:
            resp = requests.get(f"{self.base_url}/health", timeout=10)
            return resp.status_code == 200
        except:
            return False

